    int nPoints = nPointsEvaluated.get() + nPointsOutsideDEM.get();
    if (nPoints > 0) {
      double failurePercentage = (double) nPointsOutsideDEM.get() / nPoints * 100.0;
      if (failurePercentage > 50) {
        issueStore.add(
          new Graphwide(
